// StreamProtocol is an adaptive streaming protocol: HLS or DASH.
type StreamProtocol string

// Values of StreamProtocol.
const (
	StreamProtocolDASH StreamProtocol = "dash"
	StreamProtocolHLS  StreamProtocol = "hls"
)

// Manifest returns the protocol's manifest container (the URL extension) and media type; ok is false for an unknown protocol.
func (p StreamProtocol) Manifest() (container VideoContainer, contentType string, ok bool) {
	switch p {
	case "dash":
		return "mpd", "application/dash+xml", true
	case "hls":
		return "m3u8", "application/vnd.apple.mpegurl", true
	}
	return "", "", false
}

// SegmentFormat is a stream segment container: fmp4 (CMAF, the default) or ts (MPEG-TS, HLS only).
type SegmentFormat string

// Values of SegmentFormat.
const (
	SegmentFormatFMP4 SegmentFormat = "fmp4"
	SegmentFormatTS   SegmentFormat = "ts"
)

// Protocols returns the stream protocols a segment format is available for (nil for an unknown format).
func (f SegmentFormat) Protocols() []StreamProtocol {
	switch f {
	case "fmp4":
		return []StreamProtocol{"dash", "hls"}
	case "ts":
		return []StreamProtocol{"hls"}
	}
	return nil
}

// Stream limits.
const (
	// DefaultSegmentFormat is the segment format the server uses when a URL names none.
	DefaultSegmentFormat SegmentFormat = "fmp4"
	// MaxRenditions is the most renditions a stream URL may ask for.
	MaxRenditions = 8
	// RenditionMin and RenditionMax bound a rendition (the short side of the frame, in pixels).
	RenditionMin = 64
	RenditionMax = 4320
	// SegmentDurationMin and SegmentDurationMax bound the segment duration in seconds.
	SegmentDurationMin = 1
	SegmentDurationMax = 30
)

