// ErrorKind is the kind of the server's JSON error envelope. It is an error, so an *HTTPError
// matches its kind with errors.Is (errors.Is(err, xtandard.ErrorKindNotFound)).
type ErrorKind string //nolint:errname // kinds are constant sentinels named like the server's kinds

// Values of ErrorKind.
const (
	// ErrorKindUnknown is HTTP 500: internal server error.
	ErrorKindUnknown ErrorKind = "unknown"
	// ErrorKindInvalidURL is HTTP 400: invalid url.
	ErrorKindInvalidURL ErrorKind = "invalid_url"
	// ErrorKindUnauthorized is HTTP 403: invalid signature.
	ErrorKindUnauthorized ErrorKind = "unauthorized"
	// ErrorKindForbidden is HTTP 403: forbidden.
	ErrorKindForbidden ErrorKind = "forbidden"
	// ErrorKindExpired is HTTP 404: url expired.
	ErrorKindExpired ErrorKind = "expired"
	// ErrorKindNotFound is HTTP 404: source image not found.
	ErrorKindNotFound ErrorKind = "not_found"
	// ErrorKindSourceTooLarge is HTTP 422: source image too large.
	ErrorKindSourceTooLarge ErrorKind = "source_too_large"
	// ErrorKindLimitExceeded is HTTP 422: image exceeds processing limits.
	ErrorKindLimitExceeded ErrorKind = "limit_exceeded"
	// ErrorKindUnsupported is HTTP 422: unsupported image format.
	ErrorKindUnsupported ErrorKind = "unsupported"
	// ErrorKindCorrupt is HTTP 422: image cannot be decoded.
	ErrorKindCorrupt ErrorKind = "corrupt"
	// ErrorKindHashMismatch is HTTP 422: source hash mismatch.
	ErrorKindHashMismatch ErrorKind = "hash_mismatch"
	// ErrorKindNotAcceptable is HTTP 406: no acceptable image format.
	ErrorKindNotAcceptable ErrorKind = "not_acceptable"
	// ErrorKindUpstreamError is HTTP 502: upstream error.
	ErrorKindUpstreamError ErrorKind = "upstream_error"
	// ErrorKindUpstreamTimeout is HTTP 504: upstream timeout.
	ErrorKindUpstreamTimeout ErrorKind = "upstream_timeout"
	// ErrorKindOverloaded is HTTP 429: too many requests.
	ErrorKindOverloaded ErrorKind = "overloaded"
	// ErrorKindUnavailable is HTTP 503: service unavailable.
	ErrorKindUnavailable ErrorKind = "unavailable"
	// ErrorKindTimeout is HTTP 504: processing timeout.
	ErrorKindTimeout ErrorKind = "timeout"
	// ErrorKindCanceled is HTTP 499: request canceled.
	ErrorKindCanceled ErrorKind = "canceled"
	// ErrorKindInternal is HTTP 500: internal server error.
	ErrorKindInternal ErrorKind = "internal"
)

// Error implements error: the kind itself ("not_found").
func (k ErrorKind) Error() string { return string(k) }

// ErrorKindFor returns the error kind of a plain-text error response: the kind whose status and
// public message match (the server writes the message alone when Accept does not list JSON).
func ErrorKindFor(status int, message string) (ErrorKind, bool) {
	switch {
	case status == 400 && message == "invalid url":
		return ErrorKindInvalidURL, true
	case status == 403 && message == "invalid signature":
		return ErrorKindUnauthorized, true
	case status == 403 && message == "forbidden":
		return ErrorKindForbidden, true
	case status == 404 && message == "url expired":
		return ErrorKindExpired, true
	case status == 404 && message == "source image not found":
		return ErrorKindNotFound, true
	case status == 422 && message == "source image too large":
		return ErrorKindSourceTooLarge, true
	case status == 422 && message == "image exceeds processing limits":
		return ErrorKindLimitExceeded, true
	case status == 422 && message == "unsupported image format":
		return ErrorKindUnsupported, true
	case status == 422 && message == "image cannot be decoded":
		return ErrorKindCorrupt, true
	case status == 422 && message == "source hash mismatch":
		return ErrorKindHashMismatch, true
	case status == 406 && message == "no acceptable image format":
		return ErrorKindNotAcceptable, true
	case status == 502 && message == "upstream error":
		return ErrorKindUpstreamError, true
	case status == 504 && message == "upstream timeout":
		return ErrorKindUpstreamTimeout, true
	case status == 429 && message == "too many requests":
		return ErrorKindOverloaded, true
	case status == 503 && message == "service unavailable":
		return ErrorKindUnavailable, true
	case status == 504 && message == "processing timeout":
		return ErrorKindTimeout, true
	case status == 499 && message == "request canceled":
		return ErrorKindCanceled, true
	case status == 500 && message == "internal server error":
		return ErrorKindInternal, true
	}
	return ErrorKindUnknown, false
}

// Status returns the HTTP status the server answers an error kind with (0 for an unknown kind).
func (k ErrorKind) Status() int {
	switch k {
	case "unknown":
		return 500
	case "invalid_url":
		return 400
	case "unauthorized":
		return 403
	case "forbidden":
		return 403
	case "expired":
		return 404
	case "not_found":
		return 404
	case "source_too_large":
		return 422
	case "limit_exceeded":
		return 422
	case "unsupported":
		return 422
	case "corrupt":
		return 422
	case "hash_mismatch":
		return 422
	case "not_acceptable":
		return 406
	case "upstream_error":
		return 502
	case "upstream_timeout":
		return 504
	case "overloaded":
		return 429
	case "unavailable":
		return 503
	case "timeout":
		return 504
	case "canceled":
		return 499
	case "internal":
		return 500
	}
	return 0
}
